-- Ghana: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'gh-evat-pilot', id, '2022-10-01', 1, 'https://ukgcc.com.gh/wp-content/uploads/2023/03/GRA-E-VAT-Presentation-to-UKGCC-MAR-10-2023.pdf', 0, '[]', NULL, 'none', 'unreviewed' FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gh-evat-pilot', 'en', 'The E-VAT pilot goes live with about fifty large taxpayers', 'The GRA began piloting the Certified Invoicing System with roughly fifty large taxpayers. The published plan from this period had Phase 1 running to June 2023, Phase 2 to December 2023 and all VAT-registered taxpayers onboarded by December 2024. None of those dates was met.', '["Read the 2023 phase plan as intent rather than as record"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'gh-evat-phase1', id, '2024-05-21', 0, 'https://gra.gov.gh/gra-invites-businesses-to-e-vat-implementation-meeting/', 0, '[]', NULL, 'b2b', 'unreviewed' FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gh-evat-phase1', 'en', 'Phase 1 onboarding: six hundred VAT-registered taxpayers', 'The GRA called six hundred named VAT-registered taxpayers to mandatory onboarding meetings in Accra. This is the phase the 2023 plan had scheduled for March to June 2023; it happened roughly a year late.', '["Superseded by the general duty under Act 1151"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'gh-evat-phase2', id, '2024-09-05', 0, 'https://gra.gov.gh/implementation-of-electronic-invoicing-of-value-added-tax-phase-two/', 0, '[]', NULL, 'b2b', 'unreviewed' FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gh-evat-phase2', 'en', 'Phase 2 onboarding: a further two thousand taxpayers', 'A further two thousand VAT-registered taxpayers were named for onboarding across seven Accra tax offices. The GRA described the purpose as real-time monitoring of VAT transactions. No GRA notice was issued for any later phase.', '["Superseded by the general duty under Act 1151"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'gh-act1151-cis-duty', id, '2026-01-01', 0, 'https://gra.gov.gh/news/portfolio/notice-to-all-vat-registered-taxpayers/', 1, '[{"label": "GRA E-VAT", "url": "https://gra.gov.gh/e-services/e-vat/"}]', NULL, 'b2b', 'live' FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gh-act1151-cis-duty', 'en', 'Act 1151 makes certified-invoicing a general duty on every taxable person', 'The Value Added Tax Act, 2025 (Act 1151) replaced Act 870 and, at section 43(2), requires every taxable person to issue tax invoices through a Certified Invoicing System integrated with the Commissioner-General''s. The obligation stopped being a phased programme aimed at named taxpayers. The same date abolished the COVID-19 Health Recovery Levy, took the headline rate to 20%, raised the goods registration threshold to GHS 750,000, removed the threshold for services entirely, abolished the VAT Flat Rate Scheme, and raised the invoicing penalty ceiling a hundredfold.', '["If you are VAT-registered in Ghana, you are in scope now", "Service providers: there is no registration threshold at all -- register within 30 days of commencing taxable activity", "Integrate an accredited system, or use the GRA''s free E-VAT software"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'gh-fed-expenditure-approved', id, '2026-07-28', 0, 'https://www.citinewsroom.com/2026/07/parliament-approves-gra-deal-to-roll-out-fiscal-electronic-device-policy/', 1, '[{"label": "GRA Taxpayers'' Portal", "url": "https://taxpayersportal.com"}]', NULL, 'none', 'live' FROM countries WHERE code = 'GH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('gh-fed-expenditure-approved', 'en', 'Parliament approves the fiscal electronic device rollout', 'Parliament approved a multi-year expenditure commitment for the Fiscal Electronic Device policy under Act 966, targeting forty thousand devices at retail points of sale. Reporting had the pilot concluding in August 2026 with deployment to follow. This is retail fiscalisation hardware rather than a change to the invoicing duty, which Act 1151 already made general.', '["Retailers: expect device deployment, starting with mid-sized shops", "Act 966 fiscal receipts already satisfy the invoicing duty under Act 1151 s.43(9)"]');

